#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;
    long long total = (long long)n * (n - 1) / 2;
    long long max_idx = (long long)n * (n - 1);
    vector<vector<long long>> dp_table(n + 1, vector<long long>(max_idx + 1, 0));
    vector<vector<long long>> dp1_table(n + 1, vector<long long>(max_idx + 1, 0));
    dp_table[1][total] = 1;
    for (int i = 2; i <= n; ++i) {
        long long lower_bound = total - (long long)(i - 1) * (i - 2) / 2;
        long long upper_bound = total + (long long)(i - 1) * (i - 2) / 2;
        for (long long x = lower_bound; x <= upper_bound; ++x) {
            for (int diff = -i + 1; diff < i; ++diff) {
                long long idx = x + diff;
                if (0 <= idx && idx <= max_idx) {
                    long long val = (dp_table[i - 1][x] * (i - abs(diff))) % mod;
                    dp_table[i][idx] = (dp_table[i][idx] + val) % mod;
                }
            }
        }
    }
    for (int i = 2; i <= n; ++i) {
        long long lower_bound = total - (long long)(i - 1) * (i - 2) / 2;
        long long upper_bound = total + (long long)(i - 1) * (i - 2) / 2;
        for (long long x = lower_bound; x <= upper_bound; ++x) {
            long long val = (dp1_table[i - 1][x] * i) % mod;
            dp1_table[i][x] = val;
        }
        for (int i2 = 2; i2 <= n; ++i2) {
            long long lower_bound2 = total - (long long)(i2 - 1) * (i2 - 2) / 2;
            long long upper_bound2 = total + (long long)(i2 - 1) * (i2 - 2) / 2;
            for (long long x = lower_bound2; x <= upper_bound2; ++x) {
                for (int d = 1; d < i2; ++d) {
                    long long idx = x - d;
                    if (0 <= idx && idx <= max_idx) {
                        long long val = (dp_table[i2 - 1][x] * (i2 - d)) % mod;
                        dp1_table[i2][idx] = (dp1_table[i2][idx] + val) % mod;
                    }
                }
            }
        }
    }
    long long result = 0;
    for (long long x = total + 1; x <= max_idx; ++x) {
        result = (result + dp1_table[n][x]) % mod;
    }
    cout << result << "\n";
    return 0;
}
